    if (!sel || !hint) return;
    const value = sel.value.trim();
    if (!value) {
      hint.textContent = "\u5148\u770B\u5168\u90E8\u5DF2\u5BFC\u5165\u89C6\u9891\uFF0C\u4E5F\u53EF\u4EE5\u6309\u7528\u9014\u6536\u7A84\u3002";
      return;
    }
    hint.textContent = collectionHint(value);
    persistCollection(value);
    if (selectId === "vk-assets-collection") loadVideoList();
