        const effectiveText = effectiveType === "direct" ? "\u76F4\u8FDE" : effectiveType === "custom" ? `\u81EA\u5B9A\u4E49 \xB7 ${endpoint.proxy_url || legacyProxy}` : "\u5168\u5C40\u4EE3\u7406";
        let host = "";
