  window.discoverCodexAuth = async function() {
    codexAuthState.busyAction = "discover";
    codexAuthState.error = "";
    codexAuthState.message = "";
    renderCodexSubscribeDetail(false);
    try {
      const res = await fetch("/v1/subscription-auth/codex/discover", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({})
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        throw new Error(json?.error?.message || json?.message || "\u68C0\u6D4B\u5931\u8D25");
      }
      codexAuthState.status = json.status || codexAuthState.status;
      codexAuthState.message = json.message || "\u5DF2\u68C0\u6D4B\u672C\u673A Codex \u767B\u5F55\u6001";
    } catch (err) {
      codexAuthState.error = err.message || String(err);
    } finally {
      codexAuthState.busyAction = "";
      renderCodexSubscribeDetail(false);
    }
  };
  window.refreshCodexAuthToken = async function() {
    codexAuthState.busyAction = "refresh";
    codexAuthState.error = "";
    codexAuthState.message = "";
    renderCodexSubscribeDetail(false);
    try {
      const res = await fetch("/v1/subscription-auth/codex/refresh", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({})
      });
      const json = await res.json();
      if (!res.ok || json.success === false) {
        throw new Error(json?.error?.message || json?.message || "\u5237\u65B0\u5931\u8D25");
      }
      codexAuthState.status = json.status || codexAuthState.status;
      codexAuthState.message = json.message || "Token \u72B6\u6001\u5DF2\u66F4\u65B0";
    } catch (err) {
      codexAuthState.error = err.message || String(err);
    } finally {
      codexAuthState.busyAction = "";
      renderCodexSubscribeDetail(false);
    }
  };
  window.loadGrokAuthStatus = async function() {
    grokAuthState.loading = true;
    grokAuthState.error = "";
    renderGrokSubscribeDetail(false);
    try {
      const res = await fetch("/v1/subscription-auth/grok/status");
      const json = await res.json();
      if (!res.ok) throw new Error(json?.error?.message || "\u52A0\u8F7D\u72B6\u6001\u5931\u8D25");
      grokAuthState.status = json;
    } catch (err) {
      grokAuthState.error = err.message || String(err);
    } finally {
      grokAuthState.loading = false;
      renderGrokSubscribeDetail(false);
    }
  };
  window.refreshGrokAuth = async function() {
    grokAuthState.busyAction = "refresh";
    grokAuthState.error = "";
    grokAuthState.message = "";
    renderGrokSubscribeDetail(false);
    try {
      const res = await fetch("/v1/subscription-auth/grok/refresh", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({})
      });
      const json = await res.json();
      if (!res.ok || !json.success) throw new Error(json?.error?.message || "\u5237\u65B0 Token \u5931\u8D25");
      grokAuthState.message = "Token \u5237\u65B0\u6210\u529F\uFF01";
      await loadGrokAuthStatus();
    } catch (err) {
      grokAuthState.error = err.message || String(err);
    } finally {
      grokAuthState.busyAction = "";
      renderGrokSubscribeDetail(false);
    }
  };
