  function renderWebSearchHistoryHtml(entries) {
    if (!entries.length) return '<div class="media-gen-tip">\u6682\u65E0\u672C\u5730\u641C\u7D22\u5386\u53F2\u3002</div>';
    return '<div class="media-gen-history">' + entries.map((entry) => {
      const query = entry.prompt || "\u672A\u8BB0\u5F55\u67E5\u8BE2\u8BCD";
      const timestamp = entry.timestamp ? new Date(entry.timestamp).toLocaleString("zh-CN", { hour12: false }) : "";
      const provider = entry.provider || "";
      return '<div class="media-gen-history-item" style="align-items:flex-start;"><div style="flex:1;min-width:0;"><div class="media-gen-history-prompt">' + escapeHtml(query) + '</div><div class="media-gen-history-meta">' + escapeHtml(timestamp + (provider ? " \xB7 " + provider : "")) + '</div></div><div style="display:flex;gap:6px;">' + (entry.file_path ? '<button class="btn" style="padding:4px 8px;font-size:11px;" onclick="viewWebSearchHistory(' + escapeHtml(JSON.stringify(entry.id)) + ')">\u67E5\u770B</button>' : "") + '<button class="btn" style="padding:4px 8px;font-size:11px;" onclick="deleteMediaHistoryEntry(' + escapeHtml(JSON.stringify("web_search")) + ", " + escapeHtml(JSON.stringify(entry.id)) + ')">\u5220\u9664</button></div></div>';
    }).join("") + "</div>";
  }
  window.viewWebSearchHistory = async function(historyId) {
    const url = mediaHistoryPreviewUrl(historyId);
    if (!url) {
      showToast("\u8BE5\u5386\u53F2\u8BB0\u5F55\u65E0\u5173\u8054\u6587\u4EF6", "danger");
      return;
    }
    let data = null;
    try {
      const res = await fetch(url);
      data = await res.json();
    } catch (err) {
      showToast("\u52A0\u8F7D\u641C\u7D22\u7ED3\u679C\u5931\u8D25: " + (err.message || err), "danger");
      return;
    }
    const query = escapeHtml(data.query || "\u672A\u8BB0\u5F55\u67E5\u8BE2\u8BCD");
    const provider = escapeHtml(data.provider || "");
    const answer = data.answer ? '<div class="ws-answer"><strong>\u6458\u8981\uFF1A</strong>' + escapeHtml(data.answer) + "</div>" : "";
    const results = Array.isArray(data.results) ? data.results : [];
    const listHtml = results.length ? results.map((item, i) => {
      const title = escapeHtml(item.title || "(\u65E0\u6807\u9898)");
      const link = item.url ? escapeHtml(item.url) : "";
      const snippet = item.snippet ? '<div class="ws-snippet">' + escapeHtml(item.snippet) + "</div>" : "";
      return '<div class="ws-item"><div class="ws-title">' + (link ? '<a href="' + link + '" target="_blank" rel="noopener noreferrer">' + (i + 1) + ". " + title + "</a>" : i + 1 + ". " + title) + "</div>" + (link ? '<div class="ws-url">' + link + "</div>" : "") + snippet + "</div>";
    }).join("") : '<div class="ws-empty">\u672A\u627E\u5230\u76F8\u5173\u7ED3\u679C\u3002</div>';
    const html = '<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8"><title>Shrimp</title><style>body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;max-width:900px;margin:24px auto;padding:0 20px;color:#222;background:#fafafa}h1{font-size:18px;margin:0 0 4px}.ws-meta{color:#888;font-size:12px;margin-bottom:16px}.ws-answer{background:#fff;border:1px solid #e0e0e0;border-radius:8px;padding:12px 16px;margin-bottom:16px;font-size:14px;line-height:1.6}.ws-item{background:#fff;border:1px solid #e0e0e0;border-radius:8px;padding:10px 14px;margin-bottom:10px}.ws-title{font-size:14px;font-weight:600}.ws-title a{color:#1a73e8;text-decoration:none}.ws-title a:hover{text-decoration:underline}.ws-url{font-size:11px;color:#888;word-break:break-all;margin-top:2px}.ws-snippet{font-size:13px;color:#555;margin-top:6px;line-height:1.5}.ws-empty{color:#888;padding:20px;text-align:center}</style></head><body><h1>Shrimp \xB7 \u8054\u7F51\u641C\u7D22\u7ED3\u679C</h1><div class="ws-meta">\u67E5\u8BE2\u8BCD\uFF1A' + query + (provider ? " \xB7 \u670D\u52A1\u5546\uFF1A" + provider : "") + "</div>" + answer + '<div class="ws-list">' + listHtml + "</div></body></html>";
    const w = window.open("", "Shrimp");
    if (!w) {
      showToast("\u5F39\u7A97\u88AB\u6D4F\u89C8\u5668\u62E6\u622A\uFF0C\u8BF7\u5141\u8BB8\u540E\u91CD\u8BD5", "danger");
      return;
    }
    w.document.open();
    w.document.write(html);
    w.document.close();
  };
