  async function api7(path, init2) {
    const res = await fetch(path, {
      headers: { "Content-Type": "application/json", ...init2?.headers || {} },
      ...init2
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data?.error?.message || `HTTP ${res.status}`);
    return data;
  }
