  function escapeHtml3(value) {
    return String(value || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function clipPlayerRoot() {
    return document.getElementById("clip-player-root");
  }
  function normalizeClipPlayback(input) {
    const videoId = String(input.video_id || "").trim();
    const start = Number(input.start_seconds);
    const end = Number(input.end_seconds);
    if (!videoId) return { ok: false, error: "video_id is required" };
    if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) {
      return { ok: false, error: "end_seconds must be greater than start_seconds" };
    }
    return {
      ok: true,
      video_id: videoId,
      start_seconds: start,
      end_seconds: end,
      src: `/v1/video-kb/assets/${encodeURIComponent(videoId)}/video`,
      title: String(input.title || "").trim(),
      quote: String(input.quote || "").trim(),
      source_url: String(input.source_url || "").trim()
    };
  }
  function fmtTime2(seconds) {
    const m = Math.floor(Math.max(0, seconds) / 60);
    const s = Math.floor(Math.max(0, seconds) % 60);
    return `${m}:${String(s).padStart(2, "0")}`;
  }
  function clipPlayerClose() {
    const root4 = clipPlayerRoot();
    if (!root4) return;
    root4.innerHTML = "";
  }
  function clipPlayerOpen(input) {
    const root4 = clipPlayerRoot();
    if (!root4) return;
    const clip = normalizeClipPlayback(input);
    if (!clip.ok) return;
    const fallback = clip.source_url ? `<a class="clip-player-fallback" href="${escapeHtml3(clip.source_url)}" target="_blank" rel="noreferrer">\u6253\u5F00\u539F\u94FE\u63A5</a>` : "";
    root4.innerHTML = `
    <div class="clip-player-bar">
      <div class="clip-player-meta">
        <div class="clip-player-title">${escapeHtml3(clip.title || "\u89C6\u9891\u7247\u6BB5")}</div>
        <div class="clip-player-range">${fmtTime2(clip.start_seconds)} \u2013 ${fmtTime2(clip.end_seconds)}</div>
        ${clip.quote ? `<div class="clip-player-quote">${escapeHtml3(clip.quote)}</div>` : ""}
        <div class="clip-player-status" id="clip-player-status"></div>
        ${fallback}
      </div>
      <video class="clip-player-video" controls preload="metadata" src="${clip.src}"></video>
      <button class="clip-player-close" type="button" onclick="window.clipPlayerClose()">\u5173\u95ED</button>
    </div>
  `;
    const video = root4.querySelector("video");
    const status = root4.querySelector("#clip-player-status");
    if (!video) return;
    video.addEventListener("loadedmetadata", () => {
      video.currentTime = clip.start_seconds;
      video.play().catch(() => {
      });
    });
    video.addEventListener("timeupdate", () => {
      if (video.currentTime >= clip.end_seconds) video.pause();
    });
    video.addEventListener("error", () => {
      if (status) status.textContent = "\u672C\u5730\u89C6\u9891\u7F3A\u5931";
    });
  }
  window.clipPlayerOpen = clipPlayerOpen;
  window.clipPlayerClose = clipPlayerClose;

